def load_config(path):
    f = open(path)
    data = json.load(f)
    if data['timeout'] == None:
        data['timeout'] = 30
    if data['retries'] == None:
        data['retries'] = 3
    for k in data.keys():
        if type(data[k]) == str:
            data[k] = data[k].strip()
    return data

def fetch_all(urls, config):
    results = []
    for i in range(len(urls)):
        tries = 0
        while tries < config['retries']:
            try:
                r = requests.get(urls[i], timeout=config['timeout'])
                results.append(r.json())
                break
            except:
                tries = tries + 1
    return results
